/// <summary>
/// Base class for PricingAttribute table <c>MCRCustCategoryHierarchy</c>.
/// </summary>
internal abstract class GUPPricingAttributeMCRCustCategoryHierarchy extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
protected MCRCustCategoryHierarchy getTableRecord(Common _pricingObject)
{
    SalesTable               salesTable = _pricingObject as SalesTable;
    MCRCustCategoryHierarchy mCRCustCategoryHierarchy;

    if (salesTable)
    {
        mCRCustCategoryHierarchy = MCRCustCategoryHierarchy::find(GUPPricingAttributeMCRCustCategory::findByCustomer(salesTable.custTable_CustAccount().RecId).CategoryHierarchy);
    }

    return mCRCustCategoryHierarchy;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbds_2, qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(CustTable));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(MCRCustCategory));
        qbds.addLink(fieldNum(CustTable, RecId), fieldNum(MCRCustCategory, Customer));
        qbds.joinMode(JoinMode::ExistsJoin);

        qbds_2 = qbds.addDataSource(tableNum(MCRCustCategoryHierarchy));
        qbds_2.addLink(fieldNum(MCRCustCategory, CategoryHierarchy), fieldNum(MCRCustCategoryHierarchy, RecId));
        qbds_2.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds_2);
        }
    }

    return qbds_2;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
